// src/App.tsx - Chrome Dino Endless Runner Game
// Generated by Coalesce SDLC Engine for CUSTOM-OO6N
// Summary: subway surfers game

import React, { useEffect, useRef, useState, useCallback } from 'react';

interface Obstacle {
  x: number;
  y: number;
  width: number;
  height: number;
  type: 'cactus_small' | 'cactus_double' | 'cactus_large' | 'bird';
  birdAltitude?: 'low' | 'mid' | 'high';
}

interface Cloud {
  x: number;
  y: number;
  speed: number;
}

interface Star {
  x: number;
  y: number;
  size: number;
  twinkle: number;
}

export default function ChromeDinoGame() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'GAME_OVER'>('IDLE');
  const [score, setScore] = useState<number>(0);
  const [highScore, setHighScore] = useState<number>(() => {
    try {
      return Number(localStorage.getItem('coalesce_dino_hi') || 0);
    } catch {
      return 0;
    }
  });
  const [isNightMode, setIsNightMode] = useState<boolean>(false);
  const [isMuted, setIsMuted] = useState<boolean>(false);

  // Sound generator using Web Audio API
  const audioCtxRef = useRef<any>(null);
  const playBeep = useCallback((freq: number, type: OscillatorType = 'square', duration = 0.08) => {
    if (isMuted) return;
    try {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioContextClass) return;
      if (!audioCtxRef.current) {
        audioCtxRef.current = new AudioContextClass();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') {
        ctx.resume();
      }
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      gain.gain.setValueAtTime(0.09, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + duration);
    } catch {
      // Audio autoplay policy fallback
    }
  }, [isMuted]);

  // Game physics & entity state held in refs for 60fps render loop
  const stateRef = useRef({
    gameState: 'IDLE' as 'IDLE' | 'PLAYING' | 'GAME_OVER',
    dinoY: 172,
    dinoVy: 0,
    isJumping: false,
    isDucking: false,
    groundY: 220,
    speed: 6.0,
    score: 0,
    highScore: 0,
    distanceCounter: 0,
    legFrame: 0,
    animTimer: 0,
    wingFrame: 0,
    obstacles: [] as Obstacle[],
    clouds: [
      { x: 120, y: 50, speed: 0.8 },
      { x: 380, y: 70, speed: 1.1 },
      { x: 620, y: 40, speed: 0.9 },
    ] as Cloud[],
    stars: [
      { x: 60, y: 30, size: 2, twinkle: 0 },
      { x: 180, y: 75, size: 1.5, twinkle: 1 },
      { x: 320, y: 45, size: 2, twinkle: 2 },
      { x: 490, y: 65, size: 1.5, twinkle: 0 },
      { x: 670, y: 35, size: 2, twinkle: 1 },
      { x: 740, y: 80, size: 1, twinkle: 2 },
    ] as Star[],
    nextObstacleDist: 90,
    groundBumps: [0, 40, 95, 160, 240, 310, 400, 490, 580, 680, 770],
    isNightMode: false,
  });

  useEffect(() => {
    stateRef.current.highScore = highScore;
  }, [highScore]);

  useEffect(() => {
    stateRef.current.isNightMode = isNightMode;
  }, [isNightMode]);

  const startGame = useCallback(() => {
    const s = stateRef.current;
    s.gameState = 'PLAYING';
    s.dinoY = 172;
    s.dinoVy = 0;
    s.isJumping = false;
    s.isDucking = false;
    s.speed = 6.2;
    s.score = 0;
    s.distanceCounter = 0;
    s.obstacles = [];
    s.nextObstacleDist = 80;
    setScore(0);
    setGameState('PLAYING');
    playBeep(440, 'square', 0.06);
  }, [playBeep]);

  const handleJump = useCallback(() => {
    const s = stateRef.current;
    if (s.gameState === 'IDLE' || s.gameState === 'GAME_OVER') {
      startGame();
      return;
    }
    if (s.gameState === 'PLAYING' && !s.isJumping) {
      s.isJumping = true;
      s.dinoVy = -12.8;
      playBeep(640, 'square', 0.08);
    }
  }, [startGame, playBeep]);

  const setDuckingState = useCallback((ducking: boolean) => {
    const s = stateRef.current;
    if (s.gameState === 'PLAYING') {
      s.isDucking = ducking;
      // Fast drop if ducking in midair
      if (ducking && s.isJumping && s.dinoVy < 2) {
        s.dinoVy = 5.0;
      }
    }
  }, []);

  // Keyboard controls
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space' || e.code === 'ArrowUp' || e.code === 'KeyW') {
        e.preventDefault();
        handleJump();
      } else if (e.code === 'ArrowDown' || e.code === 'KeyS') {
        e.preventDefault();
        setDuckingState(true);
      }
    };

    const onKeyUp = (e: KeyboardEvent) => {
      if (e.code === 'ArrowDown' || e.code === 'KeyS') {
        setDuckingState(false);
      } else if (e.code === 'Space' || e.code === 'ArrowUp' || e.code === 'KeyW') {
        const s = stateRef.current;
        if (s.isJumping && s.dinoVy < -5) {
          s.dinoVy = -5; // variable jump height
        }
      }
    };

    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    };
  }, [handleJump, setDuckingState]);

  // Main 60FPS Canvas Animation Loop
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animId: number;
    let lastTime = performance.now();

    const loop = (currentTime: number) => {
      const dt = Math.min((currentTime - lastTime) / 1000, 0.1);
      lastTime = currentTime;

      const s = stateRef.current;
      const W = canvas.width;
      const H = canvas.height;
      const groundY = s.groundY;

      // Update game physics if running
      if (s.gameState === 'PLAYING') {
        // Dino vertical physics
        if (s.isJumping) {
          s.dinoY += s.dinoVy;
          s.dinoVy += 0.72; // Gravity
          const normalY = s.isDucking ? groundY - 30 : groundY - 48;
          if (s.dinoY >= normalY) {
            s.dinoY = normalY;
            s.dinoVy = 0;
            s.isJumping = false;
          }
        } else {
          s.dinoY = s.isDucking ? groundY - 30 : groundY - 48;
        }

        // Running animation
        s.animTimer += dt;
        if (s.animTimer > 0.08) {
          s.animTimer = 0;
          s.legFrame = (s.legFrame + 1) % 2;
          s.wingFrame = (s.wingFrame + 1) % 2;
        }

        // Score distance increment
        s.distanceCounter += s.speed * dt * 8;
        if (s.distanceCounter >= 1) {
          const added = Math.floor(s.distanceCounter);
          const oldScore = s.score;
          s.score += added;
          s.distanceCounter -= added;
          setScore(s.score);

          // Milestone beep every 100 points
          if (Math.floor(s.score / 100) > Math.floor(oldScore / 100)) {
            playBeep(880, 'sine', 0.1);
            setTimeout(() => playBeep(1100, 'sine', 0.12), 120);
          }

          // Gradual speed acceleration
          if (s.speed < 13.5) {
            s.speed += 0.0035;
          }

          // Automatic night mode toggle every 500 points
          const shouldNight = Math.floor(s.score / 500) % 2 === 1;
          if (shouldNight !== s.isNightMode) {
            s.isNightMode = shouldNight;
            setIsNightMode(shouldNight);
          }
        }

        // Move and spawn clouds
        for (const cloud of s.clouds) {
          cloud.x -= cloud.speed * (s.speed / 6);
          if (cloud.x < -80) {
            cloud.x = W + Math.random() * 80;
            cloud.y = 30 + Math.random() * 60;
          }
        }

        // Move ground terrain bumps
        for (let i = 0; i < s.groundBumps.length; i++) {
          s.groundBumps[i] -= s.speed;
          if (s.groundBumps[i] < -20) {
            s.groundBumps[i] = W + Math.random() * 30;
          }
        }

        // Spawn obstacles
        s.nextObstacleDist -= s.speed * dt * 10;
        if (s.nextObstacleDist <= 0) {
          // Choose obstacle type
          const allowBirds = s.score > 120;
          const rand = Math.random();
          let obs: Obstacle;

          if (allowBirds && rand > 0.72) {
            const altRand = Math.random();
            const alt: 'low' | 'mid' | 'high' = altRand > 0.6 ? 'low' : altRand > 0.3 ? 'mid' : 'high';
            const birdY = alt === 'high' ? groundY - 95 : alt === 'mid' ? groundY - 60 : groundY - 35;
            obs = {
              x: W + 20,
              y: birdY,
              width: 42,
              height: 32,
              type: 'bird',
              birdAltitude: alt,
            };
          } else if (rand > 0.45) {
            obs = {
              x: W + 20,
              y: groundY - 50,
              width: 26,
              height: 50,
              type: 'cactus_large',
            };
          } else if (rand > 0.22) {
            obs = {
              x: W + 20,
              y: groundY - 35,
              width: 36,
              height: 35,
              type: 'cactus_double',
            };
          } else {
            obs = {
              x: W + 20,
              y: groundY - 35,
              width: 18,
              height: 35,
              type: 'cactus_small',
            };
          }

          s.obstacles.push(obs);
          // Min distance between obstacles depends on speed
          s.nextObstacleDist = 55 + Math.random() * 65;
        }

        // Move obstacles and check collisions
        const dinoBox = s.isDucking
          ? { x: 62, y: s.dinoY + 6, w: 50, h: 24 }
          : { x: 62, y: s.dinoY + 4, w: 32, h: 42 };

        for (let i = s.obstacles.length - 1; i >= 0; i--) {
          const obs = s.obstacles[i];
          obs.x -= s.speed;

          // AABB Collision detection with slight padding for fairness
          const obsBox = {
            x: obs.x + 3,
            y: obs.y + 3,
            w: obs.width - 6,
            h: obs.height - 6,
          };

          const collided =
            dinoBox.x < obsBox.x + obsBox.w &&
            dinoBox.x + dinoBox.w > obsBox.x &&
            dinoBox.y < obsBox.y + obsBox.h &&
            dinoBox.y + dinoBox.h > obsBox.y;

          if (collided) {
            s.gameState = 'GAME_OVER';
            setGameState('GAME_OVER');
            playBeep(180, 'sawtooth', 0.25);
            if (s.score > s.highScore) {
              s.highScore = s.score;
              setHighScore(s.score);
              try {
                localStorage.setItem('coalesce_dino_hi', String(s.score));
              } catch {}
            }
            break;
          }

          // Remove offscreen
          if (obs.x < -80) {
            s.obstacles.splice(i, 1);
          }
        }
      }

      // --- RENDERING ---
      const themeBg = s.isNightMode ? '#181412' : '#fbf9f5';
      const mainColor = s.isNightMode ? '#e8e2d7' : '#29231e';
      const accentColor = s.isNightMode ? '#b49a6a' : '#75634a';

      // Clear canvas
      ctx.fillStyle = themeBg;
      ctx.fillRect(0, 0, W, H);

      // Night sky stars & moon
      if (s.isNightMode) {
        ctx.fillStyle = '#b49a6a';
        ctx.beginPath();
        ctx.arc(W - 80, 45, 14, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = themeBg;
        ctx.beginPath();
        ctx.arc(W - 86, 42, 12, 0, Math.PI * 2);
        ctx.fill();

        for (const star of s.stars) {
          ctx.fillStyle = star.twinkle % 2 === 0 ? '#b49a6a' : '#e8e2d7';
          ctx.fillRect(star.x, star.y, star.size, star.size);
        }
      }

      // Draw clouds
      ctx.fillStyle = s.isNightMode ? '#342b23' : '#d8cbb4';
      for (const cloud of s.clouds) {
        ctx.fillRect(cloud.x, cloud.y + 6, 42, 8);
        ctx.fillRect(cloud.x + 8, cloud.y, 24, 14);
        ctx.fillRect(cloud.x + 18, cloud.y - 4, 14, 8);
      }

      // Draw ground line & terrain dots
      ctx.strokeStyle = mainColor;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, groundY);
      ctx.lineTo(W, groundY);
      ctx.stroke();

      ctx.fillStyle = mainColor;
      for (const bumpX of s.groundBumps) {
        ctx.fillRect(bumpX, groundY + 4, 4, 2);
        ctx.fillRect(bumpX + 12, groundY + 9, 2, 2);
        ctx.fillRect(bumpX + 22, groundY + 5, 6, 2);
      }

      // Draw obstacles
      for (const obs of s.obstacles) {
        if (obs.type === 'bird') {
          // Bird
          ctx.fillStyle = accentColor;
          ctx.fillRect(obs.x + 10, obs.y + 10, 22, 10);
          ctx.fillRect(obs.x + 30, obs.y + 6, 8, 8);
          ctx.fillRect(obs.x + 36, obs.y + 8, 8, 4);
          ctx.fillStyle = s.isNightMode ? '#181412' : '#ffffff';
          ctx.fillRect(obs.x + 34, obs.y + 8, 2, 2);
          ctx.fillStyle = accentColor;
          ctx.fillRect(obs.x + 4, obs.y + 12, 8, 4);
          if (s.wingFrame % 2 === 0) {
            ctx.fillRect(obs.x + 14, obs.y - 6, 10, 16);
            ctx.fillRect(obs.x + 18, obs.y - 12, 6, 8);
          } else {
            ctx.fillRect(obs.x + 14, obs.y + 18, 10, 14);
            ctx.fillRect(obs.x + 18, obs.y + 30, 6, 6);
          }
        } else {
          // Cactus
          ctx.fillStyle = s.isNightMode ? '#667b5b' : '#3d5234';
          const stemW = Math.max(6, Math.floor(obs.width / 3));
          ctx.fillRect(obs.x + Math.floor(obs.width / 3), obs.y, stemW, obs.height);
          if (obs.width >= 20) {
            ctx.fillRect(obs.x, obs.y + Math.floor(obs.height * 0.35), 6, Math.floor(obs.height * 0.35));
            ctx.fillRect(obs.x, obs.y + Math.floor(obs.height * 0.35), Math.floor(obs.width / 3), 5);
          }
          if (obs.width >= 28) {
            const rx = obs.x + Math.floor(obs.width * 0.65);
            ctx.fillRect(rx, obs.y + Math.floor(obs.height * 0.25), 6, Math.floor(obs.height * 0.35));
            ctx.fillRect(obs.x + Math.floor(obs.width / 3), obs.y + Math.floor(obs.height * 0.5), Math.floor(obs.width / 3), 5);
          }
        }
      }

      // Draw Dinosaur
      const dinoX = 60;
      const isDead = s.gameState === 'GAME_OVER';
      ctx.fillStyle = mainColor;

      if (s.isDucking) {
        // Ducking posture
        ctx.fillRect(dinoX, s.dinoY + 10, 48, 18);
        ctx.fillRect(dinoX + 40, s.dinoY + 6, 18, 14);
        ctx.fillStyle = isDead ? '#a84f43' : s.isNightMode ? '#181412' : '#ffffff';
        ctx.fillRect(dinoX + 48, s.dinoY + 8, isDead ? 4 : 3, isDead ? 4 : 3);
        ctx.fillStyle = mainColor;
        ctx.fillRect(dinoX - 8, s.dinoY + 14, 10, 8);
        ctx.fillRect(dinoX - 14, s.dinoY + 18, 8, 6);
        if (s.isJumping) {
          ctx.fillRect(dinoX + 12, s.dinoY + 28, 6, 2);
          ctx.fillRect(dinoX + 28, s.dinoY + 28, 6, 2);
        } else if (s.legFrame % 2 === 0) {
          ctx.fillRect(dinoX + 12, s.dinoY + 28, 5, 3);
          ctx.fillRect(dinoX + 28, s.dinoY + 26, 5, 2);
        } else {
          ctx.fillRect(dinoX + 12, s.dinoY + 26, 5, 2);
          ctx.fillRect(dinoX + 28, s.dinoY + 28, 5, 3);
        }
      } else {
        // Upright posture
        ctx.fillRect(dinoX + 20, s.dinoY, 22, 16);
        ctx.fillRect(dinoX + 24, s.dinoY + 16, 16, 6);
        ctx.fillRect(dinoX + 32, s.dinoY + 12, 12, 4);
        ctx.fillStyle = isDead ? '#a84f43' : s.isNightMode ? '#181412' : '#ffffff';
        ctx.fillRect(dinoX + 28, s.dinoY + 4, 3, 3);
        ctx.fillStyle = mainColor;
        ctx.fillRect(dinoX + 12, s.dinoY + 14, 18, 22);
        ctx.fillRect(dinoX + 6, s.dinoY + 20, 26, 16);
        ctx.fillRect(dinoX + 30, s.dinoY + 24, 7, 3);
        ctx.fillRect(dinoX + 35, s.dinoY + 27, 2, 4);
        ctx.fillRect(dinoX - 2, s.dinoY + 22, 10, 8);
        ctx.fillRect(dinoX - 8, s.dinoY + 26, 8, 6);
        ctx.fillRect(dinoX - 14, s.dinoY + 30, 8, 4);
        if (s.isJumping) {
          ctx.fillRect(dinoX + 12, s.dinoY + 36, 5, 8);
          ctx.fillRect(dinoX + 22, s.dinoY + 36, 5, 8);
        } else if (s.legFrame % 2 === 0) {
          ctx.fillRect(dinoX + 10, s.dinoY + 36, 5, 12);
          ctx.fillRect(dinoX + 10, s.dinoY + 46, 8, 3);
          ctx.fillRect(dinoX + 24, s.dinoY + 36, 5, 6);
          ctx.fillRect(dinoX + 24, s.dinoY + 40, 7, 3);
        } else {
          ctx.fillRect(dinoX + 10, s.dinoY + 36, 5, 6);
          ctx.fillRect(dinoX + 10, s.dinoY + 40, 7, 3);
          ctx.fillRect(dinoX + 24, s.dinoY + 36, 5, 12);
          ctx.fillRect(dinoX + 24, s.dinoY + 46, 8, 3);
        }
      }

      // Draw Score in Canvas
      ctx.fillStyle = mainColor;
      ctx.font = '700 16px "Courier New", monospace';
      ctx.textAlign = 'right';
      const formattedScore = String(s.score).padStart(5, '0');
      const formattedHi = String(s.highScore).padStart(5, '0');
      ctx.fillText(`HI ${formattedHi}  ${formattedScore}`, W - 24, 32);

      // Overlay if IDLE
      if (s.gameState === 'IDLE') {
        ctx.fillStyle = s.isNightMode ? 'rgba(24, 20, 18, 0.72)' : 'rgba(251, 249, 245, 0.78)';
        ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = mainColor;
        ctx.textAlign = 'center';
        ctx.font = '600 20px "Courier New", monospace';
        ctx.fillText('PRESS SPACE TO RUN', W / 2, H / 2 - 10);
        ctx.font = '13px system-ui, sans-serif';
        ctx.fillStyle = accentColor;
        ctx.fillText('Jump: Space / Up Arrow  ·  Duck: Down Arrow', W / 2, H / 2 + 18);
      } else if (s.gameState === 'GAME_OVER') {
        ctx.fillStyle = s.isNightMode ? 'rgba(24, 20, 18, 0.76)' : 'rgba(251, 249, 245, 0.82)';
        ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = '#a84f43';
        ctx.textAlign = 'center';
        ctx.font = '700 24px "Courier New", monospace';
        ctx.fillText('G A M E   O V E R', W / 2, H / 2 - 16);
        ctx.font = '14px system-ui, sans-serif';
        ctx.fillStyle = mainColor;
        ctx.fillText(`Score: ${s.score}   ·   High Score: ${s.highScore}`, W / 2, H / 2 + 14);
        ctx.font = '12px system-ui, sans-serif';
        ctx.fillStyle = accentColor;
        ctx.fillText('Press Space or click Restart to Play Again', W / 2, H / 2 + 38);
      }

      animId = requestAnimationFrame(loop);
    };

    animId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(animId);
  }, [playBeep]);

  return (
    <div
      style={{
        minHeight: '100vh',
        background: isNightMode ? '#1c1713' : '#f5f2ec',
        color: isNightMode ? '#f5f2ec' : '#29231e',
        fontFamily: 'Inter, system-ui, sans-serif',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        padding: '1.5rem',
        boxSizing: 'border-box',
        transition: 'background 0.3s ease, color 0.3s ease',
      }}
    >
      <header
        style={{
          width: '100%',
          maxWidth: 820,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: '1rem',
          borderBottom: isNightMode ? '1px solid #342b23' : '1px solid #d8cbb4',
          paddingBottom: '0.8rem',
        }}
      >
        <div>
          <h1 style={{ margin: 0, fontSize: '1.4rem', fontWeight: 700, letterSpacing: '-0.02em', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <span>🦖</span>
            <span>Chrome Dino Endless Runner</span>
          </h1>
          <p style={{ margin: '0.2rem 0 0', fontSize: '0.82rem', color: isNightMode ? '#b49a6a' : '#75634a' }}>
            Ticket CUSTOM-OO6N · Autonomous SDLC Game Implementation
          </p>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
          <button
            type="button"
            onClick={() => setIsNightMode((v) => !v)}
            style={{
              padding: '0.35rem 0.75rem',
              borderRadius: 6,
              border: isNightMode ? '1px solid #75634a' : '1px solid #d8cbb4',
              background: isNightMode ? '#29231e' : '#fbf9f5',
              color: isNightMode ? '#f5f2ec' : '#29231e',
              cursor: 'pointer',
              fontSize: '0.8rem',
              fontWeight: 500,
            }}
          >
            {isNightMode ? '☀️ Day Mode' : '🌙 Night Mode'}
          </button>
          <button
            type="button"
            onClick={() => setIsMuted((v) => !v)}
            style={{
              padding: '0.35rem 0.75rem',
              borderRadius: 6,
              border: isNightMode ? '1px solid #75634a' : '1px solid #d8cbb4',
              background: isNightMode ? '#29231e' : '#fbf9f5',
              color: isNightMode ? '#f5f2ec' : '#29231e',
              cursor: 'pointer',
              fontSize: '0.8rem',
              fontWeight: 500,
            }}
          >
            {isMuted ? '🔇 Unmute' : '🔊 Sound'}
          </button>
        </div>
      </header>

      {/* Main Game Stage */}
      <div
        style={{
          width: '100%',
          maxWidth: 820,
          background: isNightMode ? '#29231e' : '#fbf9f5',
          border: isNightMode ? '1px solid #342b23' : '1px solid #d8cbb4',
          borderRadius: 12,
          padding: '1.2rem',
          boxShadow: '0 8px 24px rgba(0,0,0,0.06)',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          boxSizing: 'border-box',
        }}
      >
        <canvas
          ref={canvasRef}
          width={800}
          height={280}
          onClick={handleJump}
          style={{
            width: '100%',
            maxWidth: 800,
            height: 'auto',
            aspectRatio: '800 / 280',
            borderRadius: 8,
            cursor: gameState === 'PLAYING' ? 'pointer' : 'default',
            border: isNightMode ? '1px solid #342b23' : '1px solid #e8e2d7',
          }}
        />

        {/* Action Controls & Interactive Buttons */}
        <div
          style={{
            marginTop: '1.2rem',
            width: '100%',
            maxWidth: 800,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            flexWrap: 'wrap',
            gap: '0.8rem',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
            <button
              type="button"
              onClick={handleJump}
              style={{
                padding: '0.55rem 1.4rem',
                borderRadius: 8,
                border: 'none',
                background: '#b49a6a',
                color: '#1c1713',
                fontWeight: 700,
                fontSize: '0.9rem',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '0.4rem',
              }}
            >
              <span>▲</span>
              <span>{gameState === 'PLAYING' ? 'JUMP' : 'START / RESTART'}</span>
            </button>

            <button
              type="button"
              onMouseDown={() => setDuckingState(true)}
              onMouseUp={() => setDuckingState(false)}
              onTouchStart={() => setDuckingState(true)}
              onTouchEnd={() => setDuckingState(false)}
              style={{
                padding: '0.55rem 1.2rem',
                borderRadius: 8,
                border: isNightMode ? '1px solid #75634a' : '1px solid #d8cbb4',
                background: isNightMode ? '#342b23' : '#e8e2d7',
                color: isNightMode ? '#f5f2ec' : '#29231e',
                fontWeight: 600,
                fontSize: '0.88rem',
                cursor: 'pointer',
              }}
            >
              ▼ DUCK (HOLD)
            </button>

            {gameState === 'GAME_OVER' && (
              <button
                type="button"
                onClick={startGame}
                style={{
                  padding: '0.55rem 1.2rem',
                  borderRadius: 8,
                  border: '1px solid #667b5b',
                  background: '#667b5b',
                  color: '#ffffff',
                  fontWeight: 600,
                  fontSize: '0.88rem',
                  cursor: 'pointer',
                }}
              >
                ↺ PLAY AGAIN
              </button>
            )}
          </div>

          <div style={{ fontSize: '0.82rem', color: isNightMode ? '#b49a6a' : '#75634a' }}>
            Keyboard: <strong>Space</strong> / <strong>↑</strong> to Jump · <strong>↓</strong> to Duck
          </div>
        </div>
      </div>
    </div>
  );
}
